// SnakeStickCore 공개 API. 이름은 계약이고 구현은 실행자가 채운다.
import SlopDisk    // ../slopdisk
import NTFS3G      // ../NTFS3G
import WIMLib      // ../WIMLib

@location('SnakeStickCore/Sources/SnakeStickCore/Model.swift')
public enum InstallerTarget: Sendable, Codable {
    case device(bsdName: String)                       // "disk4". 코어가 /dev/rdisk4로 바꾼다.
    case image(path: String, size: UInt64)             // build. 없는 파일을 sparse로 만든다.
}
public struct InstallerOptions: Sendable, Codable {
    public var volumeLabel: String?                    // nil이면 ISOInfo.volumeLabel
    public var verifyAfterWrite = true
    public var useCA2023Bootloaders = false
}
public struct InstallerRequest: Sendable, Codable {
    public var isoPath: String
    public var target: InstallerTarget
    public var options: InstallerOptions
}
public enum Phase: Int, Sendable, Codable, CaseIterable {   // Figma 8단계
    case openISO = 1, prepareTarget, writePartitionTable, checkPartitions,
         formatNTFS, copyFiles, prepareBootPartition, verify
}
public struct Progress: Sendable, Codable {
    public var phase: Phase
    public var fraction: Double                         // 전체 진행 0…1. 단계별 가중치는 실행자가 정하되 단계 6이 대부분이다.
    public var detail: String?                          // 단계 6의 현재 경로
    public var estimatedRemaining: TimeInterval?        // 단계 6만 (P15)
}
public enum InstallerEvent: Sendable, Codable {
    case progress(Progress)
    case log(String)                                    // P17
    case finished(InstallerResult)
    case failed(InstallerError)
}
public struct InstallerResult: Sendable, Codable { public var elapsed: TimeInterval; public var verified: Bool }
public struct InstallerError: Error, Sendable, Codable {
    public var phase: Phase
    public var message: String                          // 사용자용 (code#strings 상태 07 본문 형식)
    public var underlying: String                       // 개발자용 (에러 타입과 errno)
    public var targetState: String                      // "부팅할 수 없는 상태" 등
}

@location('SnakeStickCore/Sources/SnakeStickCore/ISOInfo.swift')
public struct ISOInfo: Sendable, Codable {
    public var volumeLabel: String                      // P5
    public var fileSize: UInt64
    public var windowsVersion: String                   // P6, "Windows 11 25H2"
    public var build: Int
    public var architecture: String                     // "x64" | "ARM64" | "x86"
    public var supportsCA2023: Bool                     // build >= 26200 (P7)
    public var requiredBytes: UInt64                    // estimatedVolumeSize + FAT + GPT + 정렬 (결정 25)
}
imagine func inspectISO(at path: String) async throws -> ISOInfo {
    requirements(`
        PVD에서 레이블을 읽고(P5), hdiutil로 마운트해(P3) sources/boot.wim의 XML(P6)과 estimatedVolumeSize를 얻은 뒤 detach한다.
        boot.wim이 없거나 마운트가 실패하면 InstallerError(phase: .openISO)를 던진다.
    `);
    ensure(`§15의 테스트 ISO에서 volumeLabel == "SNAKETEST", build == 26200, architecture == "x64", supportsCA2023 == true`);
    ensure(`빈 파일 → throws, 메시지에 "not a Windows ISO"`);
}

@location('SnakeStickCore/Sources/SnakeStickCore/DiskCandidates.swift')
public struct DiskCandidate: Sendable, Codable, Identifiable {
    public var id: String { bsdName }
    public var bsdName: String                          // "disk4"
    public var model: String                            // "SanDisk Ultra USB 3.0"
    public var sizeBytes: UInt64
    public var protocolName: String                     // "USB"
    public var partitionCount: Int
    public var volumes: [(name: String, fileSystem: String)]
    public var isInternal: Bool, isRemovable: Bool, isBootDisk: Bool
    public var isEligible: Bool                         // P8
}
imagine func listDiskCandidates() throws -> [DiskCandidate] {
    requirements(`P8. DiskArbitration만 쓴다. diskutil을 파싱하지 않는다. 시동 디스크는 statfs("/")와 "/System/Volumes/Data"의 f_mntfromname에서 whole disk를 구한다.`);
    ensure(`반환에 isBootDisk == true인 항목이 없다`);
    ensure(`DA 설명 딕셔너리를 주입하는 순수 함수 classify(description:) 가 내장·시동·이미지 디스크를 걸러낸다 (단위 테스트)`);
}

@location('SnakeStickCore/Sources/SnakeStickCore/Installer.swift')
imagine func runInstaller(_ request: InstallerRequest, events: @escaping @Sendable (InstallerEvent) -> Void) async throws -> InstallerResult {
    requirements(`
        code#pipeline 의 8단계를 순서대로 실행한다. 각 단계 시작에 .progress를 보낸다.
        .device 대상이면 getuid() == 0을 요구한다 (아니면 InstallerError(phase: .prepareTarget, "root required")).
        .image 대상이면 파일을 만들고 hdiutil attach -nomount로 붙인 뒤 같은 경로를 밟고, 끝에 detach한다.
        Task 취소를 단계 사이와 copyTree progress에서 본다 (P16). 취소되면 정리(§11) 뒤 CancellationError를 던진다.
        실패하면 정리 뒤 InstallerError를 던지고 .failed도 보낸다.
    `);
    ensure(`§15 통합 테스트: .image 대상으로 끝까지 돌고, 결과 이미지를 읽기 전용으로 붙여 GPT healthy·NTFS 트리 일치·FAT 네 파일 일치`);
    ensure(`copyTree 중 취소 → CancellationError, 마운트·attach가 남지 않음`);
}

// 단계 3. SlopDisk로 code#layout 을 만든다. FAT를 끝에 두는 방법: NTFS를 .remaining으로 넣어 LastUsableLBA를 알아낸 뒤 줄이고, FAT를 at:으로 넣는다 (F6).
imagine func writePartitionTable(devicePath: String, label: String) throws -> (ntfs: SDPartition, fat: SDPartition) {
    requirements(`
        let device = try SDRawDevice(path: devicePath, acknowledging: .dataLossRisk)
        let disk = try SDDisk(device: device, ignoringExistingTable: true)
        try disk.withTransaction { txn in
            txn.clear()
            var ntfs = try txn.addPartition(.remaining, type: .microsoftBasicData, label: label)      // begin = 첫 정렬 경계, end = LastUsableLBA
            let sectorsPerMiB = UInt64(1 << 20) / UInt64(disk.sectorSize)
            let fatSectors = sectorsPerMiB                                                         // 결정 23: 1 MiB
            let fatBegin = ((ntfs.end + 1 - fatSectors) / sectorsPerMiB) * sectorsPerMiB           // 1 MiB 아래로 정렬
            ntfs = try txn.resizePartition(ntfs.id, to: .size(.bytes((fatBegin - ntfs.begin) * UInt64(disk.sectorSize))))
            let fat = try txn.addPartition(.size(.bytes(fatSectors * UInt64(disk.sectorSize))), type: .efiSystem, label: "UEFI:NTFS", at: fatBegin)
            try txn.commit()
            return (ntfs, fat)
        }
        // withTransaction이 끝나면 device를 해제해야 슬라이스가 생긴다 (F8). disk와 device를 이 함수 밖으로 내보내지 않는다.
    `);
    ensure(`64 MiB(512) 이미지: ntfs.index == 0, ntfs.begin == 2048, fat.index == 1, fat.end == 131038, fat.begin == 131038 + 1 - 2048 - ((131038 + 1 - 2048) % 2048) 또는 그와 같은 1 MiB 정렬 값, fat.size.bytes == 1_048_576`);
    ensure(`fat.end == LastUsableLBA (뒤에 빈 구간이 없다)`);
    ensure(`gpt -r show  의 두 행이 SlopDisk의 begin/end와 같다 (slopdisk 테스트 헬퍼와 같은 방식)`);
    ensure(`디스크가 "2 MiB + GPT"보다 작으면 트랜잭션 전에 InstallerError (C10)`);
}

// runInstaller의 골격. 세부는 §3~§11.
let tmp = makeTempDir()                                    // P4
defer { cleanup(tmp) }                                     // §11: FAT 언마운트 → ISO detach → 이미지 detach → 승인 콜백 해제 → 디렉터리 삭제

// 1
let iso = try attachISO(request.isoPath, at: tmp/iso)      // P3
let info = try inspectISO(mounted: iso)                    // P5, P6, 결정 25
if options.useCA2023Bootloaders { try extractCA2023(from: iso/sources/boot.wim, to: tmp/wim) }   // P7. 실패는 여기서 끝낸다.

// 2
let device = try resolveTarget(request.target, requiredBytes: info.requiredBytes)   // .device → P8 재검사 + C10, .image → 파일 생성 + hdiutil attach -nomount (C5)
try unmountDisk(device)                                    // diskutil unmountDisk force /dev/diskN (C8)
let guard = try MountGuard(wholeDisk: device)             // 결정 21. deinit에서 해제.

// 3
let (ntfsPart, fatPart) = try writePartitionTable(devicePath: device.raw, label: label)   // code#partition

// 4
let ntfsSlice = try waitForSlice(device, index: 1, expect: ntfsPart)   // P11, C17, C18
let fatSlice  = try waitForSlice(device, index: 2, expect: fatPart)

// 5
try NTFSVolume.format(path: ntfsSlice.raw, options: .init(label: label, sectorSize: device.sectorSize, partitionStartSector: ntfsPart.begin))   // C16

// 6
let volume = try NTFSVolume(path: ntfsSlice.raw, mode: .readWrite)
let summary = try volume.copyTree(from: iso) { p in try Task.checkCancellation(); report(p) }   // P15, P16
if options.useCA2023Bootloaders { try replaceBootloaders(in: volume, from: tmp/wim, arch: info.architecture) }   // P7, 결정 28
try volume.close()

// 7
try run("/sbin/newfs_msdos", "-v", "UEFI_NTFS", fatSlice.raw)            // 결정 23. FAT 종류는 newfs_msdos에 맡긴다 (U8).
guard.allowNextMount(of: fatSlice)                                        // 결정 21
try run("/usr/sbin/diskutil", "mount", "-mountPoint", tmp/efi, fatSlice.buffered)
try copyLoaders(to: tmp/efi/efi/boot)                                     // 결정 24: bootx64.efi, bootaa64.efi, ntfs_x64.efi, ntfs_aa64.efi (서명본, 이름에서 _signed 제거)
try scrubMacOSMetadata(tmp/efi)                                           // C6
try run("/usr/sbin/diskutil", "unmount", fatSlice.buffered)

// 8
try verify(ntfsSlice, fatSlice, device, against: iso, options)            // P12

// 앱 ↔ 헬퍼 데몬. 메시지는 Codable. 데몬은 한 번에 작업 하나만 받는다.
enum HelperRequest: Codable {
    case start(InstallerRequest, authorization: Data)      // AuthorizationExternalForm (P10)
    case cancel
    case version                                           // 앱과 데몬의 버전 불일치 감지
}
enum HelperReply: Codable {
    case accepted
    case rejected(reason: String)                          // 인증 실패, 이미 실행 중, 버전 불일치, 대상 자격 없음(P8 재검사)
    case event(InstallerEvent)                             // 진행·로그·완료·실패. 시작 뒤 스트림으로 온다.
    case version(String)
}
// 데몬: 피어가 같은 Team ID의 pl.unstabler.aislop.SnakeStick일 때만 세션을 받는다 (P9).
// 앱: 세션이 끊기면(데몬 크래시) 07 오류로 보인다.
